def test_emoji_and_cjk_pass_through(text):
    # Diacritics stripped; emoji and CJK characters pass through intact
    result = normalize(text)
    for ch in text:
        if (
            not unicodedata.combining(ch)
            and not unicodedata.decomposition(ch)
        ):
            assert ch in result
    assert_no_combining_marks(result)
